/** @jsxImportSource ./ */
import { it, expect } from 'vitest'
import { Hono } from '../hono'
import { jsxRenderer } from '../middleware/jsx-renderer'
import { renderToReadableStream, Suspense } from './streaming'
const st = async (s: any) => { const r = renderToReadableStream(s).getReader(); let o=''; const d=new TextDecoder(); for(;;){const {done,value}=await r.read(); if(done)break; o+=d.decode(value)} return o }
const A = async () => <b>A</b>
const AA = async () => [<i>1</i>, 'x<y', [<A />, async () => 1]] as any
it('sync/nested/async', async () => {
  const F = () => [<li>a</li>, 'a<b', [<li>c</li>, <A />], Promise.resolve(<u>p</u>)] as any
  expect(String(await (<div><F /></div>).toString())).toBe('<div><li>a</li>a&lt;b<li>c</li><b>A</b><u>p</u></div>')
  const G = async () => [<i>1</i>, 'x<y', [<A />]] as any
  expect(String(await (<div><G /></div>).toString())).toBe('<div><i>1</i>x&lt;y<b>A</b></div>')
})
it('stream', async () => {
  const G = async () => [<i>1</i>, 'x<y', [<A />]] as any
  const o = await st(<Suspense fallback="f"><G /></Suspense>)
  expect(o).toContain('<i>1</i>x&lt;y<b>A</b>')
  const o2 = await st(<div><G /></div>)
  expect(o2).toContain('<div><i>1</i>x&lt;y<b>A</b></div>')
})
it('renderer', async () => {
  const app = new Hono()
  app.use(jsxRenderer(({children}) => <html><head></head><body>{children}</body></html>, {stream:true}))
  const G = async () => [<title>T</title>, <A />] as any
  app.get('/', (c) => c.render(<G />))
  const t = await (await app.request('/')).text()
  expect(t).toContain('<head><title>T</title></head>')
})
EOF
